def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    remainder = remaining % item
    closeness = item - remainder
    return np.where(remaining >= 0, -closeness, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    count = np.floor(remaining / item)
    return np.where(remaining >= 0, count, -np.inf)

